func (a *irlearn_app) drawList() {
	fb := a.fb
	w, _ := fb.Size()
	items := len(a.remotes) + 1
	// カーソルが見えるようにスクロール
	if a.cursor < a.scroll {
		a.scroll = a.cursor
	}
	if a.cursor >= a.scroll+irlearn_listLines {
		a.scroll = a.cursor - irlearn_listLines + 1
	}
	for row := 0; row < irlearn_listLines; row++ {
		i := a.scroll + row
		if i >= items {
			break
		}
		y := int16(irlearn_listTop + row*irlearn_lineH)
		label := "+ Register"
		col := irlearn_cyan
		if i < len(a.remotes) {
			label = a.remotes[i].Name
			col = irlearn_white
		}
		if i == a.cursor {
			fb.FillRectangle(4, y, w-8, irlearn_lineH, irlearn_dark)
			tinyfont.WriteLine(fb, &freesans.Regular9pt7b, 8, y+13, ">", irlearn_yellow)
		}
		tinyfont.WriteLine(fb, &freesans.Regular9pt7b, 22, y+13, label, col)
	}
	if items > irlearn_listLines {
		tinyfont.WriteLine(fb, &freesans.Regular9pt7b, w-40, irlearn_listTop+13, irlearn_itoa(a.cursor+1)+"/"+irlearn_itoa(items), irlearn_gray)
	}
}

func (a *irlearn_app) drawMenu() {
	fb := a.fb
	w, _ := fb.Size()
	const mw, mh = 120, 3*irlearn_lineH + 16
	x := (w - mw) / 2
	y := int16(90)
	fb.FillRectangle(x-2, y-2, mw+4, mh+4, irlearn_gray)
	fb.FillRectangle(x, y, mw, mh, irlearn_black)
	for i, item := range irlearn_menuItems {
		yy := y + 8 + int16(i)*irlearn_lineH
		col := irlearn_white
		if i == a.menuIdx {
			fb.FillRectangle(x+4, yy, mw-8, irlearn_lineH, irlearn_dark)
			col = irlearn_yellow
		}
		tinyfont.WriteLine(fb, &freesans.Regular9pt7b, x+12, yy+13, item, col)
	}
}

// ---- 入力 ----

// input は 1 回のポーリングで検出したイベント (押した瞬間、または上下左右の 1 ステップ)。
type irlearn_input struct {
	sw1, sw2              bool
	up, down, left, right bool
}

type irlearn_inputState struct {
	sw1, sw2   badge.Button
	joy        *badge.Joystick
	prev1      bool
	prev2      bool
	dirHeld    int // 0 なし、1 上、2 下、3 左、4 右
	nextRepeat time.Time
}

func irlearn_newInput() *irlearn_inputState {
	sw1, sw2 := badge.NewButtons()
	joy := badge.NewJoystick()
	joy.Calibrate(300 * time.Millisecond)
	return &irlearn_inputState{sw1: sw1, sw2: sw2, joy: joy}
}

const (
	irlearn_dirThreshold = 500
	irlearn_repeatFirst  = 400 * time.Millisecond
	irlearn_repeatNext   = 120 * time.Millisecond
)

func (s *irlearn_inputState) poll() irlearn_input {
	var ev irlearn_input
	p1, p2 := s.sw1.Pressed(), s.sw2.Pressed()
	ev.sw1 = p1 && !s.prev1
	ev.sw2 = p2 && !s.prev2
	s.prev1, s.prev2 = p1, p2

	x, y, _ := s.joy.Read()
	dir := 0
	switch {
	case y > irlearn_dirThreshold:
		dir = 1
	case y < -irlearn_dirThreshold:
		dir = 2
	case x < -irlearn_dirThreshold:
		dir = 3
	case x > irlearn_dirThreshold:
		dir = 4
	}
	fire := false
	if dir != s.dirHeld {
		s.dirHeld = dir
		if dir != 0 {
			fire = true
			s.nextRepeat = time.Now().Add(irlearn_repeatFirst)
		}
	} else if dir != 0 && time.Now().After(s.nextRepeat) {
		fire = true
		s.nextRepeat = time.Now().Add(irlearn_repeatNext)
	}
	if fire {
		switch dir {
		case 1:
			ev.up = true
		case 2:
			ev.down = true
		case 3:
			ev.left = true
		case 4:
			ev.right = true
		}
	}
	return ev
}

